    public static IntegrationDeliveryLog RecordOutbound(long tenantId,long integrationConfigurationId,long outboxMessageId,string correlationId,string provider,IntegrationDeliveryStatus status,long durationMilliseconds,int?httpStatusCode,string?errorCategory,DateTime createdUtc)=>new(tenantId,integrationConfigurationId,null,outboxMessageId,correlationId,provider,IntegrationDirection.Outbound,status,durationMilliseconds,httpStatusCode,errorCategory,createdUtc);
